// --- 核心数值变量：国库 ---

{
  "variable_name": "国库",
  "data_type": "Long Integer",
  "description": "衡量国家财政状况的核心指标，代表中央政府可直接支配的白银储备。",

  "value_parameters": {
    "initial_value": 1500000,
    "min_value": 0,
    "max_value": 999990000,
    "unit": "两白银"
  },

  "dynamic_rules": {
    "increase_conditions": [
      {
        "source": "全国税收",
        "description": "定期根据国家经济状况、税率政策及征收效率结算的财政收入。",
        "frequency": "按季度/年度结算（可配置）",
        "magnitude": "受经济发展水平、政策、民心等多个变量影响，动态浮动。"
      }
    ],
    "decrease_conditions": [
      {
        "source": "常规财政支出",
        "description": "涵盖所有常规性政府开销。",
        "items": [
          "军饷发放",
          "官员俸禄",
          "基础设施维护",
          "行政办公开支"
        ],
        "magnitude": "相对固定，但会随军队规模、官员数量等因素变化。"
      },
      {
        "source": "项目性财政支出",
        "description": "由具体事件或决策触发的大额非经常性支出。",
        "items": [
          "大型工程建设（如运河、长城）",
          "大规模赈灾",
          "对外战争军费"
        ],
        "magnitude": "由事件本身规模决定，波动极大。"
      }
    ],
    "time_variable_effect": {
      "name": "日常损耗",
      "description": "模拟因仓储、运输、管理及未统计的微小开支导致的财政自然流失。",
      "effect": "国库数值随时间推移缓慢减少。",
      "rate": "待定（建议设置为一个固定的每日或每月减少值）"
    }
  },

  "special_events": {
    "type": "非规律性财政变动",
    "description": "由突发或随机事件导致的国库非正常收入。",
    "examples": [
      "查抄贪官家产",
      "发现新的贵金属矿脉",
      "获得海外贸易的超额利润",
      "收到藩属国的巨额进贡"
    ],
    "trigger_condition": "由游戏内随机事件或玩家决策触发。"
  },

  "threshold_triggers": {
    "on_max_value": {
      "event_name": "盛世景明",
      "description": "当国库储量达到上限时，触发一次性的全局性积极事件。",
      "effect_details": "待定（建议效果如：全国民心大幅提升、生产力获得永久性加成、解锁特殊建筑或政策等）"
    },
    "on_min_value": {
      "event_name": "财政赤字",
      "description": "当国库储量为零时，可能触发一系列负面效果。",
      "potential_effects": [
        "军队哗变风险增加",
        "官员腐败率上升",
        "民众暴乱几率提高"
      ]
    }
  }
}

