// --- 核心数值变量：京营兵力 ---

{
  "variable_name": "京营兵力",
  "data_type": "Integer",
  "description": "衡量中央直属常备军数量与质量的核心指标。",

  "value_parameters": {
    "initial_value": 100000,
    "min_value": 0,
    "max_value": 1000000,
    "unit": "人"
  },

  "dynamic_rules": {
    "increase_conditions": [
      {
        "source": "募兵",
        "description": "通过发布募兵令、征召等方式增加兵员数量，是兵力增加的唯一途径。",
        "magnitude": "由募兵事件的规模和投入的资源决定。"
      }
    ],
    "decrease_conditions": [
      {
        "source": "逃兵",
        "description": "因士气低下、管理不善等原因导致的兵员非战斗性流失。",
        "magnitude": "通常为持续性的少量减少，受士气、俸禄发放情况影响。"
      },
      {
        "source": "欠饷",
        "description": "长期拖欠军饷导致的兵员大规模溃散或哗变。",
        "magnitude": "一次性的大幅减少，具体数值与欠饷时间、规模成正比。"
      },
      {
        "source": "清查空饷",
        "description": "核查并剔除军中虚报的名额，导致账面兵力的直接核减。",
        "magnitude": "根据清查力度和空饷的实际比例进行一次性削减。"
      },
      {
        "source": "战争伤亡",
        "description": "在战斗中产生的直接人员损失。",
        "magnitude": "根据战报结果直接扣减相应数值。"
      }
    ]
  },

  "phase_performance_mechanism": {
    "trigger_event": "清查空饷",
    "effect": {
      "name": "精锐化",
      "description": "在“清查空饷”事件后，剩余的兵员因获得了更充足的补给与更严格的训练，将随时间逐步转化为战斗力更强的精锐部队。",
      "status_tag": "精锐",
      "transformation_logic": {
        "activation": "“清查空饷”事件结束后立即启动。",
        "rate": "待定（建议设置为一个固定的每月转化百分比，如：每月5%的现存兵力获得‘精锐’标签）。",
        "process": "系统将逐步为未带标签的兵员添加‘精锐’标签，直至所有兵员转化完毕。"
      },
      "combat_effectiveness": {
        "label": "以一当十",
        "description": "带有‘精锐’标签的士兵，在战斗结算时，其战斗力权重将获得极大提升。此效果不直接增加兵力数值，而是在战斗力计算公式中作为一个高额乘数。",
        "note": "具体的战斗力加成系数可在战斗系统中另行配置。"
      }
    }
  }
}

